\label{prop-group-substructure}{{\em {\cite[Theorem~6.7 and
  Proposition~6.8]{BvdH19}}\/}} The class $\mathbf{Smp}_{\mathcal{G}}$ is a
  surreal substructure. We have the uniform cut equation
  \begin{equation}
     \forall z \in \mathbf{No} , \quad
    \Xi_{\mathbf{Smp}_{\mathcal{G}}} z = \{ \mathcal{G}
    \Xi_{\mathbf{Smp}_{\mathcal{G}}} z_L | \mathcal{G}
    \Xi_{\mathbf{Smp}_{\mathcal{G}}} z_R \}_{\mathbf{S}} .
    \label{eq-uniform-G}
  \end{equation}

Let $\mathfrak{m} \in \mathbf{Mo}^{\neq 1}$. Assume that there are $\psi \in
  \mathbf{No}_{\succ}$, $\iota \in \{ - 1, 1 \}$, $\alpha \in \{ 0 \} \cup
  \omega^{\mathbf{On}}$, $\beta \in \mathbf{On}$ and $u \in \mathbf{No}$ such
  that
  \begin{equation}
    \mathfrak{m}= \mathrm{e}^{\psi}  (L_{\beta} E_{\alpha}^u)^{\iota},
    \label{eq-standard-expansion-gen}
  \end{equation}
  with $\ensuremath{\operatorname{supp}} \psi \succ L_{\beta + 1} E_{\alpha}^u$. Then we say that
  \text{{\upshape{(\ref{eq-standard-expansion-gen})}}} is a
  {\textbf{{{\em hyperserial expansion of type I\/}}}} if
  \begin{itemize}
    \item $\beta \omega < \alpha$;

    \item $E_{\alpha}^u \in \mathbf{Mo}_{\alpha} \setminus L_{< \alpha} 
    \mathbf{Mo}_{\alpha \omega}$;

    \item $\alpha = 1 \Longrightarrow \left( \psi = 0 \text{ and $u$ is not
    tail-atomic} \right)$.
  \end{itemize}
  We say that \text{{\upshape{(\ref{eq-standard-expansion-gen})}}} is a
  {\textbf{{{\em hyperserial expansion of type II\/}}}} if $\alpha = 0$ and
  $u = \omega$, so that $E_{\alpha}^u = \omega$ and
  \begin{equation}
    \mathfrak{m}= \mathrm{e}^{\psi}  (L_{\beta} \omega)^{\iota} .
    \label{eq-st-expansion-1}
  \end{equation}

\label{lem-st-expansion-no-sign}If $\mathfrak{m}= \mathrm{e}^{\psi}  (L_{\beta}
  E_{\alpha}^u)^{\iota}$ is a hyperserial expansion of type I, then we have
  \[ \ensuremath{\operatorname{supp}} \psi \cap \ensuremath{\operatorname{supp}} u = \varnothing . \]

Let us find all the paths in the monomial $\mathfrak{m}$ of
  Example~\ref{example-st}. We have a representation
  (\ref{ex-expanded-monomial}) of $\mathfrak{m}$ as a hyperseries
  \[ \mathfrak{m}= \mathrm{e}^{2 E_{\omega^2}^{L_{\omega^{\small{2}}} \omega + 1}
     - E_1^{\frac{1}{2} L_1 \omega}}  (L_{\omega} \omega) \]
  which by Lemma~\ref{lem-st-expansion-unicity} is unique. There are nine
  paths in $\mathfrak{m}$, namely
  \begin{itemizedot}
    \item 1 path $(\mathfrak{m})$ of length $1$;

    \item 3 paths $\left( \mathfrak{m}, 2
    E_{\omega^2}^{L_{\omega^{\small{2}}} \omega + 1} \right)$, $\left(
    \mathfrak{m}, - E_1^{\frac{1}{2} L_1 \omega} \right)$, and $(\mathfrak{m},
    \omega)$ of length $2$;

    \item 3 paths $\left( \mathfrak{m}, 2
    E_{\omega^2}^{L_{\omega^{\small{2}}} \omega + 1}, L_{\omega^2} \omega
    \right)$, $\left( \mathfrak{m}, 2 E_{\omega^2}^{L_{\omega^{\small{2}}}
    \omega + 1}, 1 \right)$, $\left( \! \mathfrak{m}, - E_1^{\frac{1}{2}
    L_1 \omega}, \frac{1}{2} L_1 \omega \! \right)$ of length~$3$;

    \item 2 paths $\left( \mathfrak{m}, 2
    E_{\omega^2}^{L_{\omega^{\small{2}}} \omega + 1}, L_{\omega^2} \omega,
    \omega \right)$ and $\left( \mathfrak{m}, - E_1^{\frac{1}{2} L_1 \omega},
    \frac{1}{2} L_1 \omega, \omega \right)$ of length $4$.
  \end{itemizedot}
  Note that the paths which cannot be extended into strictly longer paths are
  those whose last value is a real number or $\omega$.

\label{inv-dec-lem}{{\em {\cite[Corollary~4.21]{BM18}}\/}} For $\mathfrak{m},
  \mathfrak{n} \in \mathbf{Mo}$, we have
  \begin{eqnarray*}
    \mathfrak{m} \sqsubseteq \mathfrak{n} & \Longleftrightarrow &
    \mathfrak{m}^{- 1} \sqsubseteq \mathfrak{n}^{- 1} .
  \end{eqnarray*}

\label{exp-dec-lem}{{\em {\cite[Proposition~4.23]{BM18}}\/}} Given $\varphi,
  a, b$ in $\mathbf{No}_{\succ}$ with $a, b \prec \ensuremath{\operatorname{supp}} \varphi$, we
  have
  \begin{eqnarray*}
    \mathrm{e}^a \sqsubseteq \mathrm{e}^b & \Longrightarrow & \mathrm{e}^{\varphi \mathbin{+\!\!\!\!+}
    a} \sqsubseteq \mathrm{e}^{\varphi \mathbin{+\!\!\!\!+} b} .
  \end{eqnarray*}

\label{exp-mon-lem}{{\em {\cite[Proposition~4.24]{BM18}}\/}} Given
  $\mathfrak{m}, \mathfrak{n} \in \mathbf{Mo}^{\succ}$ with $\log \mathfrak{m}
  \prec \mathfrak{n}$, we have
  \begin{eqnarray*}
    \mathfrak{m} \sqsubseteq \mathfrak{n} & \Longrightarrow &
    \mathrm{e}^{\mathfrak{m}} \sqsubseteq \mathrm{e}^{\mathfrak{n}} .
  \end{eqnarray*}

The condition $\mathfrak{m} \in \mathcal{E}_{\omega} [\mathfrak{n}]$ yields
  $\log \mathfrak{m} \prec \mathfrak{n}$. We have $\mathrm{e}^{\mathfrak{m}}
  \sqsubseteq \mathrm{e}^{\mathfrak{n}}$ by Lemma~\ref{exp-mon-lem}. The identity
  $\mathrm{e}^{\mathbf{Mo}^{\succ}} = \mathbf{Smp}_{\mathcal{P}}$ implies that
  $\mathrm{e}^{\mathfrak{m}} \sqsubseteq \mathrm{e}^{| r | \mathfrak{n}}$, whence
  $\mathrm{e}^{\ensuremath{\operatorname{sign}} (r) \mathfrak{m}} \sqsubseteq \mathrm{e}^{r\mathfrak{n}}$
  by Lemma~\ref{inv-dec-lem}. Lemma~\ref{exp-dec-lem} yields $\mathrm{e}^{\varphi \mathbin{+\!\!\!\!+}
  \ensuremath{\operatorname{sign}} (r) \mathfrak{m}} \sqsubseteq \mathrm{e}^{\varphi \mathbin{+\!\!\!\!+}
  r\mathfrak{n}}$. Since $\mathrm{e}^0 = 1 \sqsubseteq
  \mathrm{e}^{\delta} \in \mathbf{No}^{>}$, we may apply Lemma~\ref{exp-dec-lem}
  to $\varphi \mathbin{+\!\!\!\!+} r\mathfrak{n}$ and $\varphi \mathbin{+\!\!\!\!+} r\mathfrak{n} \mathbin{+\!\!\!\!+}
  \delta$ to obtain $\mathrm{e}^{\varphi \mathbin{+\!\!\!\!+} r\mathfrak{n}} \sqsubseteq
  \mathrm{e}^{\varphi \mathbin{+\!\!\!\!+} r\mathfrak{n} \mathbin{+\!\!\!\!+} \delta}$. We conclude using the
  transitivity of $\sqsubseteq$.

By~(\ref{eq-rich-hyperexp}), we have
  \[ E_{\alpha} \varphi = \left\{ E_{< \alpha} \varphi, \mathcal{E}_{\alpha}
     E_{\alpha}^{\varphi^{\mathbf{No}_{\succ, \alpha}}_L} |
     \mathcal{E}_{\alpha} E_{\alpha}^{\varphi^{\mathbf{No}_{\succ, \alpha}}_R}
     \right\} . \]
  Since $\varphi \sqsubseteq \psi$, we have $\varphi_L^{\mathbf{No}_{\succ,
  \alpha}} \subseteq \psi_L^{\mathbf{No}_{\succ, \alpha}}$ and
  $\varphi_R^{\mathbf{No}_{\succ, \alpha}} \subseteq
  \psi_R^{\mathbf{No}_{\succ, \alpha}}$, whence
  \[ \mathcal{E}_{\alpha} E_{\alpha}^{\varphi^{\mathbf{No}_{\succ, \alpha}}_L}
     < E_{\alpha} \psi <\mathcal{E}_{\alpha}
     E_{\alpha}^{\varphi^{\mathbf{No}_{\succ, \alpha}}_R} . \]
  Furthermore, we have $L_{\alpha} E_{< \alpha} \varphi < \psi$, so~$E_{<
  \alpha} \varphi < E_{\alpha}^{\psi}$. We conclude that $E_{\alpha}^{\varphi}
  \sqsubseteq E_{\alpha}^{\psi}$.

\label{lem-transitive-ineq}Let $\alpha, \alpha' \in \omega^{\mathbf{On}}$
  with $\alpha' \geqslant \alpha$. For $u, v \in \mathbf{No}^{>, \succ}$, we
  have
  \begin{eqnarray*}
    L_{\alpha} u <\mathcal{E}_{\alpha} v & \Longrightarrow & L_{\alpha'}
    E_{\alpha} u <\mathcal{E}_{\alpha'} E_{\alpha} v.
  \end{eqnarray*}

\label{lem-subpath-descent}Let $a \in \mathbf{No}$, let $P$ be an infinite
  path in $a$ and let $i \in \mathbb{N}$ such that every index~$k \leqslant i$
  is good for $(P, a)$. For $k \leqslant i$, let $\varphi_k :=
  (u_k)_{\succ \mathfrak{m}_k}$, $\varepsilon_k := r_k$, and $\rho_k
  := (u_k)_{\prec \mathfrak{m}_k}$, so that $ \varepsilon_0,
  \ldots, \varepsilon_{i - 1}  \in \{ - 1, 1 \}$ and
  \begin{eqnarray*}
    u_k & = & \varphi_k \mathbin{+\!\!\!\!+} \varepsilon_k \mathrm{e}^{\psi_{k + 1}} 
    (E_{\alpha_k}^{u_{k + 1}})^{\iota_k} \hspace*{\fill} (k < i)\\
    u_i & = & \varphi_i \mathbin{+\!\!\!\!+} r_i \mathrm{e}^{\psi_{i + 1}}  (L_{\beta_i}
    E_{\alpha_i}^{u_{i + 1}})^{\iota_i} \mathbin{+\!\!\!\!+} \rho_i .
  \end{eqnarray*}
  Let $\chi \in \{ 0, 1 \}$ and let $c_i \in \mathbf{No}_{\succ, \alpha_{i -
  1}}$ be a number with $c_i \lesssim u_i$ and
  \begin{equation}
    c_i = \varphi_i \mathbin{+\!\!\!\!+} \chi \ensuremath{\operatorname{sign}} (r_i) \mathrm{e}^{\psi_{i + 1}}
    \mathfrak{p}^{\iota_i}, \label{eq-cj}
  \end{equation}
  for a certain $\mathfrak{p} \in \mathbf{Mo}^{\succcurlyeq}$ with $\log
  \mathfrak{p} \prec \ensuremath{\operatorname{supp}} \psi_{i + 1}$, $\mathfrak{p} \sqsubseteq
  E_{\alpha_i}^{u_{i + 1}}$ and $\mathfrak{p} \in \mathcal{E}_{\omega}
  [E_{\alpha_i}^{u_{i + 1}}]$ whenever $\psi_{i + 1} = 0$. For~$k = i - 1,
  \ldots, 0$, we define
  \begin{equation}
    c_k := \varphi_k + \varepsilon_k \mathrm{e}^{\psi_{k + 1}} 
    (E_{\alpha_k}^{c_{k + 1}})^{\iota_k} \label{eq-config-I}
  \end{equation}
  Assume that $P$ shares a subpath with $c_i$. If $P$ shares no subpath with
  any of the numbers $\varphi_0, \psi_1, \ldots, \varphi_{i - 1}, \psi_i$,
  then we have~$c_0 \sqsubseteq a$, and $P$ shares a subpath with $c_0$.

\label{def-coding-sequence}Let $\Sigma := (\varphi_i, \varepsilon_i,
  \psi_i, \iota_i, \alpha_i)_{i \in \mathbb{N}} \in (\mathbf{No} \times \{ -
  1, 1 \} \times \mathbf{No} \times \{ - 1, 1 \} \times
  \omega^{\mathbf{On}})^{\mathbb{N}}$. We say that $\Sigma$ is a
  {{\em {\textbf{coding sequence}}\/}}{\index{coding sequence}} if for all $i
  \in \mathbb{N}$, we have
  \begin{enumeratealpha}
    \item $\psi_i \in \mathbf{No}_{\succ}$;

    \item $\varphi_{i + 1} \in \mathbf{No}_{\succ, \alpha_i} \cup \{ 0 \}$;

    \item $(\alpha_i = 1) \Longrightarrow (\psi_i = 0 \wedge (\psi_{i + 1} = 0
    \Longrightarrow \alpha_{i + 1} = 1))$;

    \item $(\varphi_{i + 1} = \psi_{i + 1} = 0) \Longrightarrow (\alpha_i
    \geqslant \alpha_{i + 1} \wedge \varepsilon_{i + 1} = \iota_{i + 1} = 1)$;

    \item \label{def-coding-sequence-e}$\exists j > i, (\varphi_j \neq 0 \vee
    \psi_j \neq 0)$.
  \end{enumeratealpha}

Let us prove the lemma by induction on $i$. The result clearly holds for~$i
  = 0$. Assuming that $a_{; i}$ is well defined, let $j > i$ be minimal such
  that $\varphi_j \neq 0$ or $\psi_j \neq 0$. Note that we have $\alpha_i
  \geqslant \alpha_{i + 1} \geqslant \cdots \geqslant \alpha_j$, so
  $E_{\alpha_i} \circ E_{\alpha_{i + 1}} \circ \cdots \circ E_{\alpha_j} =
  E_{\gamma}$ where $\gamma = \alpha_i + \alpha_{i + 1} + \cdots + {\nobreak}
  \alpha_j$. Applying~$\Phi_{; i}$ to the inequality
  \[ L_j < a < R_j \;, \]
  we obtain
  \[ \sigma_{; i}  (L_j)_{; i} < \sigma_{; i} a_{; i} < \sigma_{; i}  (R_j)_{;
     i} . \]
  Now if $\varphi_j \neq 0$, then
  \begin{eqnarray*}
    (L_j)_{; i} & \supseteq & \varphi_i + \varepsilon_i \mathrm{e}^{\psi_i} 
    (E_{\gamma} (\varphi_j - \sigma_{; j} \mathbb{R}^{>} \ensuremath{\operatorname{supp}}
    \varphi_j))^{\iota_i}\\
    (R_j)_{; i} & \supseteq & \varphi_i + \varepsilon_i \mathrm{e}^{\psi_i} 
    (E_{\gamma} (\varphi_j + \sigma_{; j} \mathbb{R}^{>} \ensuremath{\operatorname{supp}}
    \varphi_j))^{\iota_i},
  \end{eqnarray*}
  wso the number $z := \sigma_{; i} 
     \frac{a_{; i} - \varphi_i}{\varepsilon_i}$ satisfies 
  \[ \sigma_{; i} \mathrm{e}^{\psi_i}  (E_{\gamma} (\varphi_j - \sigma_{; j}
     \mathbb{R}^{>} \ensuremath{\operatorname{supp}} \varphi_j))^{\iota_i} < z < \sigma_{; i} \mathrm{e}^{\psi_i} 
     (E_{\gamma} (\varphi_j + \sigma_{; j} \mathbb{R}^{>} \ensuremath{\operatorname{supp}}
     \varphi_j))^{\iota_i} . \]
  Both in the cases when $\sigma_{; i} = 1$ and when $\sigma_{; i} = - 1$, it
  follows that the number $((a_{; i} - \varphi_i) / \varepsilon_i
  \mathrm{e}^{\psi_i})^{\iota_i}$ is bounded from below by the hyperexponential
  $E_{\gamma}$ of a number. Thus $a_{; j} = L_{\gamma} (((a_{; i} - \varphi_i)
  / (\varepsilon_i \mathrm{e}^{\psi_i}))^{\iota_i})$ is well defined and so is
  each $a_{; k}$ for $i \leqslant k < j$. If $\varphi_j = 0$, then we have
  $\psi_j \neq 0$ and


  \begin{eqnarray*}
    (L_j)_{; i} & \supseteq & \varphi_i + \varepsilon_i \mathrm{e}^{\psi_i} 
    (E_{\gamma} (\mathrm{e}^{\psi_j - \varepsilon_j \sigma_{; j} \mathbb{R}^{>}
    \ensuremath{\operatorname{supp}} \psi_j}))^{\iota_i},\\
    (R_j)_{; i} & \supseteq & \varphi_i + \varepsilon_i \mathrm{e}^{\psi_i} 
    (E_{\gamma} (\mathrm{e}^{\psi_j + \varepsilon_j \sigma_{; j} \mathbb{R}^{>}
    \ensuremath{\operatorname{supp}} \psi_j}))^{\iota_i} .
  \end{eqnarray*}
  Hence
  \[ \varepsilon_i \mathrm{e}^{\psi_i}  (E_{\gamma} (\mathrm{e}^{\psi_j -
     \varepsilon_j \sigma_{; j} \mathbb{R}^{>} \ensuremath{\operatorname{supp}} \psi_j}))^{\iota_i}
     < a_{; i} - \varphi_i < \varepsilon_i \mathrm{e}^{\psi_i}  (E_{\gamma}
     (\mathrm{e}^{\psi_j + \varepsilon_j \sigma_{; j} \mathbb{R}^{>} \ensuremath{\operatorname{supp}}
     \psi_j}))^{\iota_i} \]
  Both in the cases when $\varepsilon_i = 1$ and when $\varepsilon_i = - 1$,
  it follows that $((a_{; i} - \varphi_i) / \varepsilon_i
  \mathrm{e}^{\psi_i})^{\iota_i}$ is bounded from below by the hyperexponential
  $E_{\gamma}$ of a number, so $a_{; j}$ is well defined and so is each $a_{;
  k}$ for $i \leqslant k < j$.

\label{lem-simplicity}Assume that $\Sigma$ is nested. Let $k \in
  \mathbb{N}$, $a \in \mathbf{Ad}$ and $c_k \in \mathbf{No}$ with
  \begin{equation}
    c_k = \varphi_k \mathbin{+\!\!\!\!+} \varepsilon_k \mathrm{e}^{\psi_k}
    \mathfrak{p}^{\iota_k} \label{eq-ck}
  \end{equation}
  for a certain $\mathfrak{p} \in \mathbf{Mo}^{\succcurlyeq}$ with
  $\mathfrak{p} \sqsubseteq E_{\alpha_j} a_{; k + 1}$ and $\mathfrak{p} \in
  \mathcal{E}_{\omega} [E_{\alpha_k} a_{; k + 1}]$ whenever $\psi_k = 0$. If
  $c_k \in \mathbf{Ad}_{\nearrow k}$, then we have
  \[ (c_k)_{k ;} \sqsubseteq a. \]

The proof is similar to the proof of Lemma~\ref{lem-subpath-descent}. We
  have $a_{; k} = \varphi_k \mathbin{+\!\!\!\!+} \varepsilon_k \mathrm{e}^{\psi_k} 
  (E_{\alpha_k} a_{; k + 1})^{\iota_k}$ and we must have $\ensuremath{\operatorname{supp}} \psi_k
  \succ \log \mathfrak{p}$ since $c_k = \varphi_k \mathbin{+\!\!\!\!+} \varepsilon_k
  \mathrm{e}^{\psi_k} \mathfrak{p}^{\iota_k} \in \mathbf{Ad}_{\nearrow k}$. If
  follows from the deconstruction lemmas in \Cref{subsection-decomposition}
  that $c_k \sqsubseteq a_{; k}$. This proves the result in the case when~$k =
  0$.

  Now assume that $k > 0$. Setting $c_{k - p} := \Phi_{k - p ; k} (c_k)$,
  let us prove by induction on {$p \leqslant k$}~that
  \begin{eqnarray*}
    c_{k - p} & \in & \mathbf{Ad}_{\nearrow k - p}\\
    c_{k - p} & \in & \mathbf{No}_{\succ, \alpha_{k - p - 1}}\\
    c_{k - p} & \sqsubseteq & a_{; k - p} .
  \end{eqnarray*}
  For $p = k$, the last relation yields the desired result.

  If $p = 0$, then we have $c_k \in \mathbf{Ad}_{\nearrow k}$ by assumption
  and we have shown above that {$c_k \sqsubseteq a_{; k}$}. We have $\varphi_k
  \vartriangleleft \sharp_{\alpha_{k - 1}} (c_k)$ and $\mathrm{e}^{\psi_k}
  \mathfrak{p}^{\iota_j}$ is a~monomial, so (\ref{eq-ck}) yields {$c_k =
  \sharp_{\alpha_{k - 1}} (c_k) \in \mathbf{No}_{\succ, \alpha_{k - 1}}$}.
  This deals with the case $p = 0$. In addition, we have {$c_k > 0$} because
  $k > 0$ and $c_k \in \mathbf{Ad}_{\nearrow k}$. Let us show that
  \begin{equation}
    \log c_k \prec a_{; k} . \label{eq-logck}
  \end{equation}
  If $\varphi_k \neq 0$, then this follows from the facts that $\varphi_k
  \vartriangleleft a_{; k}$ and $\varphi_k \vartriangleleft c_k$. If
  $\varphi_k = 0$ and $\psi_k \neq 0$, then $\log (c_k / \varepsilon_k) \sim
  \psi_k \sim \log (a_{; k} / \varepsilon_k) \prec a_{; k}$. If $\varphi_k =
  \psi_k = 0$, then $a_{; k} = E_{\alpha_k} a_{; k + 1}$ and $c_k
  =\mathfrak{p} \in \mathcal{E}_{\omega} [a_{; k}]$, so $\log c_k \prec a_{;
  k}$.

  Assume now that $0 < p \leqslant k$ and that the induction hypothesis holds
  for all smaller $p$. We have
  \begin{equation}
    \label{ckp} c_{k - p} = \Phi_{k - p} (c_{k - p + 1}) = \varphi_k +
    \varepsilon_k \mathrm{e}^{\psi_k}  \left( E_{\alpha_{k - p}}^{\smash{c_{k - p
    + 1}}} \right)^{\iota_k}
  \end{equation}
  Since $\Sigma$ is nested, we immediately obtain $\varphi_{k - p}
  \vartriangleleft \sharp_{\alpha_{k - p - 1}} (c_{k - p})$, whence $c_{k - p}
  \in \mathbf{No}_{\succ, \alpha_{k - p - 1}}$ as above. Since $c_{k - p - 1}
  \in \mathbf{Ad}_{\nearrow (k - p - 1)}$ and $\Sigma$ is nested, we have
  $c_{k - p} \in \mathbf{Ad}_{\nearrow (k - p)}$.
  Using~(\ref{ckp}),~(\ref{eq-logck}), and the decomposition lemmas, we
  observe that the relation $c_{k - p} \sqsubseteq a_{; k - p}$ is equivalent
  to
  \begin{equation}
    E_{\alpha_{k - p}}^{\smash{c_{k - p + 1}}} \sqsubseteq E_{\alpha_{k - p}}
    a_{; k - p + 1} . \label{eq-simpl}
  \end{equation}
  We have $c_{k - p + 1} \sqsubseteq a_{; k - p + 1}$, so $c_{k - p + 1}
  \sqsubseteq \sharp_{\alpha_{k - p}} (a_{; k - p + 1})$. Note that
  \[ E_{\alpha_{k - p}}^{\smash{\sharp_{\alpha_{k - p}} (a_{; k - p + 1})}}
     =\mathfrak{d}_{\alpha_{k - p}} (E_{\alpha_{k - p}} a_{; k - p + 1})
     \sqsubseteq E_{\alpha_{k - p}} a_{; k - p + 1} . \]
  So it is enough, in order to derive \Cref{eq-simpl}, to prove that
  $E_{\alpha_{k - p}}^{\smash{c_{k - p + 1}}} \sqsubseteq E_{\alpha_{k -
  p}}^{\smash{\sharp_{\alpha_{k - p}} (a_{; k - p + 1})}}$. Now
  \[ L_{\alpha_{k - p}} c_{k - p + 1} <\mathcal{E}_{\alpha_{k - p}}
     \sharp_{\alpha_{k - p}} (a_{; k - p + 1}) \]
  by Lemma~\ref{lem-admissible-ineq}, whence $E_{\alpha_{k - p}}^{\smash{c_{k
  - p + 1}}} \sqsubseteq E_{\alpha_{k - p}}^{\smash{\sharp_{\alpha_{k - p}}
  (a_{; k - p + 1})}}$ by Lemma~\ref{hypexp-mon-lem}.

If $\Sigma$ is nested, then for $i \in \mathbb{N}$ and $a, b \in
  \mathbf{Ne}$, we have $a \sqsubseteq b \Longleftrightarrow a_{; i}
  \sqsubseteq b_{; i}$.

If $\Sigma$ is nested, then $\mathbf{Ne} = (\mathbf{Ne}_{\nearrow
  1})_{1 ;} = \varphi_0 + \varepsilon_0 \mathrm{e}^{\psi_0} 
  (E_{\alpha_0}^{\mathbf{Ne}_{\nearrow 1}})^{\iota_0}$.

\label{eval-uniqueness-lem}{$\mbox{}$}

  \begin{enumeratealpha}
    \item \label{finite-height-case}If $T$ has finite height, then there
    exists at most one evaluation of $T$.

    \item \label{v-vprime-case}Let $v$ and $v'$ be evaluations of $T$ with $v
    (\rho_T) = v' (\rho_T)$. Then $v = v'$.
  \end{enumeratealpha}
